edits.replacement:
body #attract .arcover .aor + .aor{ margin-top:calc(var(--sp-1) * var(--attz,1)); }
/* v28.xx (cw-party-over3): the critic (screen 55, 2 of 5) wanted "a centred card with centred content and a hero that carries it": the content is centred, the accent tab sits centred on the top edge,
   the card is 720px x scale (the guide end card width) and the haul rows are in tx-1 so they read from the couch. */
body #attract .arcover{ text-align:center; min-width:calc(720px * var(--attz,1)); }
body #attract .arcover::before{ left:50%; transform:translateX(-50%); }
body #attract .arcover .aor{ color:var(--tx-1); }
body #attract .arcover .aobm{ justify-content:center !important; }
body #attract .arcover .aobmt{ text-align:center !important; }

check:
{v:'VER',what:'the run over card is centred, 720px x scale wide, content centred (critic: left-aligned box with dead space, screen 55)',
 run:function(){
   if(typeof arcadeOverEl!=='function'||typeof attEl!=='function') return 'SKIP: no arcade overlay here';
   var d, c, wasDisp, z, res=null, w;
   try{
     __topClear(); __runPrep();
     d=attEl(); wasDisp=d.style.display; d.style.display='block';
     try{ if(typeof attZ==='function') attZ(d); }catch(_z){}
     z=parseFloat(getComputedStyle(d).getPropertyValue('--attz'))||1;
     c=arcadeOverEl(); c.textContent='x'; c.style.display='block';
     w=parseFloat(getComputedStyle(c).width);
     if(getComputedStyle(c).textAlign!=='center') res='the card text is '+getComputedStyle(c).textAlign+', not centre';
     else if(Math.abs(w-720*z)>4 && w<720*z) res='the card is '+w+'px wide, not 720px x '+z;
     return res;
   } finally {
     try{ c.style.display='none'; c.textContent=''; c.removeAttribute('data-at'); d.style.display=wasDisp; }catch(_f){}
   }
 }},
